"""Outbound OpenBDX account pairing, publishing, and install synchronization.

This module deliberately uses only the Python standard library.  PuddleDuck
opens outbound HTTPS connections to OpenBDX; OpenBDX never connects into the
robot's LAN.
"""

from __future__ import annotations

import hashlib
import io
import json
import os
import platform
import re
import socket
import tempfile
import threading
import time
import uuid
from pathlib import Path
from typing import Any, Callable, Dict, Iterable, List, Optional, Tuple
from urllib.error import HTTPError, URLError
from urllib.parse import quote, urljoin, urlparse
from urllib.request import Request, urlopen


PRODUCTION_ORIGIN = "https://openbdx.org"
STAGING_ORIGIN = "https://staging.openbdx.org"
DEFAULT_ORIGIN = PRODUCTION_ORIGIN
STAGING_MARKER_NAME = ".staging"
CONFIG_FORMAT = "puddleduck_openbdx_connection_v1"
ROBOT_MODEL = "darkwing4_bdx"
ROBOT_SELECTIONS = {
    "besh": "Besh",
    "grek": "Grek",
    "oskar": "Oskar",
    "patch": "Patch",
    "red": "Red",
    "generic": "Generic",
}
AUTO_ROBOT_SELECTIONS = {"", "auto", "default"}
ROBOT_OPTION_RE = re.compile(r"(?:^|[\s,;])duck\s*[:=]\s*([a-z0-9_-]+)", re.IGNORECASE)
PAIR_POLL_SECONDS = 5.0
HEARTBEAT_SECONDS = 30.0
JOB_POLL_SECONDS = 8.0
REQUEST_TIMEOUT_SECONDS = 45.0
MAX_PUBLICATION_BYTES = 64 * 1024 * 1024
EMOTE_PREVIEW_FORMAT = "openbdx_emote_preview_v1"
EMOTE_PREVIEW_WIDTH = 854
EMOTE_PREVIEW_HEIGHT = 480
EMOTE_PREVIEW_FPS = 30
EMOTE_PREVIEW_DURATION_SECONDS = 5.0


def openbdx_origin_for_home(home: Optional[Path] = None) -> str:
    """Choose the default OpenBDX origin from ``$HOME/.staging``.

    A marker present in the runtime user's home selects staging. Production
    is the safe default for installed ducks. Explicit constructor or
    environment overrides are handled separately and take precedence.
    """
    root = Path(home) if home is not None else Path.home()
    try:
        use_staging = (root.expanduser() / STAGING_MARKER_NAME).exists()
    except OSError:
        use_staging = False
    return STAGING_ORIGIN if use_staging else PRODUCTION_ORIGIN


def configured_openbdx_origin(explicit: Optional[str] = None) -> str:
    """Resolve the configured origin in precedence order."""
    return str(
        explicit
        or os.environ.get("PUDDLEDUCK_OPENBDX_ORIGIN")
        or os.environ.get("OPENBDX_ORIGIN")
        or openbdx_origin_for_home()
    ).rstrip("/")


class OpenBDXError(RuntimeError):
    """OpenBDX HTTP/API failure with structured response details."""

    def __init__(self, message: str, *, status: int = 0, code: str = "", payload: Optional[Dict[str, Any]] = None):
        super().__init__(message)
        self.status = int(status or 0)
        self.code = str(code or "")
        self.payload = dict(payload or {})


class OpenBDXHttpClient:
    """Tiny urllib based client; injectable in tests."""

    def __init__(self, origin: str, *, timeout: float = REQUEST_TIMEOUT_SECONDS):
        parsed = urlparse(str(origin or "").strip())
        if parsed.scheme not in ("http", "https") or not parsed.netloc:
            raise ValueError("OpenBDX origin must be an http or https URL")
        self.origin = f"{parsed.scheme}://{parsed.netloc}"
        self.timeout = max(1.0, float(timeout))

    def _url(self, path: str) -> str:
        if str(path).startswith(("http://", "https://")):
            return str(path)
        return urljoin(self.origin.rstrip("/") + "/", str(path).lstrip("/"))

    def request(
        self,
        method: str,
        path: str,
        *,
        token: str = "",
        json_body: Optional[Dict[str, Any]] = None,
        data: Optional[bytes] = None,
        headers: Optional[Dict[str, str]] = None,
        expect_json: bool = True,
        timeout: Optional[float] = None,
    ) -> Any:
        request_headers = {
            "Accept": "application/json" if expect_json else "*/*",
            "User-Agent": "PuddleDuck-OpenBDX/1",
        }
        request_headers.update(headers or {})
        if token:
            request_headers["Authorization"] = f"Bearer {token}"
        body = data
        if json_body is not None:
            body = json.dumps(json_body, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
            request_headers["Content-Type"] = "application/json"
        if body is not None:
            request_headers["Content-Length"] = str(len(body))
        req = Request(self._url(path), data=body, headers=request_headers, method=str(method).upper())
        try:
            with urlopen(req, timeout=self.timeout if timeout is None else timeout) as response:
                raw = response.read()
                if not expect_json:
                    return raw, dict(response.headers.items()), int(response.status)
                if not raw:
                    return {}
                try:
                    value = json.loads(raw.decode("utf-8"))
                except Exception as exc:
                    raise OpenBDXError("OpenBDX returned invalid JSON", status=response.status) from exc
                return value
        except HTTPError as exc:
            raw = exc.read()
            payload: Dict[str, Any] = {}
            try:
                decoded = json.loads(raw.decode("utf-8")) if raw else {}
                if isinstance(decoded, dict):
                    payload = decoded
            except Exception:
                payload = {}
            message = str(payload.get("message") or payload.get("error") or exc.reason or f"HTTP {exc.code}")
            raise OpenBDXError(message, status=exc.code, code=str(payload.get("error") or ""), payload=payload) from exc
        except URLError as exc:
            raise OpenBDXError(f"OpenBDX is unreachable: {exc.reason}") from exc


class OpenBDXDuckAgent:
    """Persisted account connection and background install worker."""

    def __init__(
        self,
        policy_store: Any,
        emote_library: Any,
        state_hub: Any,
        *,
        duck_selection: Any = None,
        config_path: Optional[str] = None,
        origin: Optional[str] = None,
        client_factory: Callable[[str], OpenBDXHttpClient] = OpenBDXHttpClient,
        release_path: str = "/etc/bdx-release",
    ):
        self.policy_store = policy_store
        self.emote_library = emote_library
        self.state_hub = state_hub
        self.duck_selection = duck_selection
        self.config_path = Path(
            config_path
            or os.environ.get("PUDDLEDUCK_OPENBDX_CONFIG")
            or (Path.home() / ".config" / "openbdx" / "duck.json")
        ).expanduser().resolve()
        self.config_path.parent.mkdir(parents=True, exist_ok=True)
        configured_origin = configured_openbdx_origin(origin)
        self._client_factory = client_factory
        self._release_path = Path(release_path)
        self._lock = threading.RLock()
        self._wake = threading.Event()
        self._stop = threading.Event()
        self._thread: Optional[threading.Thread] = None
        self._busy = ""
        self._hash_cache: Dict[Tuple[str, int, int], str] = {}
        self._state = self._load_state(configured_origin)
        self.client = client_factory(str(self._state["origin"]))

    # ------------------------------------------------------------------
    # Persistence and status
    # ------------------------------------------------------------------
    def _load_state(self, configured_origin: str) -> Dict[str, Any]:
        value: Dict[str, Any] = {}
        try:
            parsed = json.loads(self.config_path.read_text(encoding="utf-8"))
            if isinstance(parsed, dict):
                value = parsed
        except (FileNotFoundError, json.JSONDecodeError, OSError):
            value = {}
        device_uuid = str(value.get("device_uuid") or "").strip()
        if not device_uuid:
            device_uuid = f"puddleduck:{uuid.uuid4()}"

        origin = str(configured_origin or DEFAULT_ORIGIN).rstrip("/")
        stored_origin = str(value.get("origin") or "").rstrip("/")
        origin_changed = bool(stored_origin and stored_origin != origin)
        environment_state = {} if origin_changed else value

        # Tokens, server IDs, publication IDs, and install jobs are scoped to
        # one OpenBDX deployment. When $HOME/.staging (or an explicit origin
        # override) changes the target, retain only the physical duck identity
        # and require a fresh pairing on the selected deployment.
        state: Dict[str, Any] = {
            "format": CONFIG_FORMAT,
            "origin": origin,
            "device_uuid": device_uuid,
            "access_token": str(environment_state.get("access_token") or ""),
            "token_expires_at": str(environment_state.get("token_expires_at") or ""),
            "profile": environment_state.get("profile") if isinstance(environment_state.get("profile"), dict) else {},
            "duck_id": str(environment_state.get("duck_id") or ""),
            "display_name": str(value.get("display_name") or socket.gethostname() or "PuddleDuck"),
            "pending": environment_state.get("pending") if isinstance(environment_state.get("pending"), dict) else {},
            "installs": environment_state.get("installs") if isinstance(environment_state.get("installs"), dict) else {},
            "published": environment_state.get("published") if isinstance(environment_state.get("published"), dict) else {},
            "last_sync_at": str(environment_state.get("last_sync_at") or ""),
            "last_error": str(environment_state.get("last_error") or ""),
        }
        self._write_state(state)
        return state

    def _write_state(self, state: Optional[Dict[str, Any]] = None) -> None:
        data = dict(state if state is not None else self._state)
        data["format"] = CONFIG_FORMAT
        temp = self.config_path.with_name(f".{self.config_path.name}.{os.getpid()}.{threading.get_ident()}.tmp")
        encoded = (json.dumps(data, indent=2, sort_keys=True, ensure_ascii=False) + "\n").encode("utf-8")
        fd = os.open(str(temp), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        try:
            with os.fdopen(fd, "wb", closefd=True) as stream:
                stream.write(encoded)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(str(temp), str(self.config_path))
            os.chmod(str(self.config_path), 0o600)
        finally:
            try:
                temp.unlink()
            except FileNotFoundError:
                pass

    def _save(self) -> None:
        with self._lock:
            self._write_state()

    def status(self) -> Dict[str, Any]:
        with self._lock:
            pending = dict(self._state.get("pending") or {})
            if pending and float(pending.get("expires_at_epoch") or 0) <= time.time():
                pending = {}
            return {
                "ok": True,
                "origin": self._state["origin"],
                "connected": bool(self._state.get("access_token") and self._state.get("duck_id")),
                "paired": bool(self._state.get("access_token")),
                "duck_id": self._state.get("duck_id") or "",
                "device_uuid": self._state["device_uuid"],
                "display_name": self._state.get("display_name") or socket.gethostname(),
                "profile": dict(self._state.get("profile") or {}),
                "pending": pending,
                "busy": self._busy,
                "last_sync_at": self._state.get("last_sync_at") or "",
                "last_error": self._state.get("last_error") or "",
                "config_path": str(self.config_path),
            }

    def start(self) -> None:
        if os.environ.get("PUDDLEDUCK_OPENBDX_ENABLED", "1").strip().lower() in {"0", "false", "no", "off"}:
            return
        with self._lock:
            if self._thread and self._thread.is_alive():
                return
            self._stop.clear()
            self._thread = threading.Thread(target=self._run, name="openbdx-duck", daemon=True)
            self._thread.start()

    def stop(self) -> None:
        self._stop.set()
        self._wake.set()
        thread = self._thread
        if thread and thread.is_alive():
            thread.join(timeout=3.0)

    # ------------------------------------------------------------------
    # Device pairing
    # ------------------------------------------------------------------
    def begin_pairing(self, display_name: Optional[str] = None) -> Dict[str, Any]:
        with self._lock:
            if self._state.get("access_token"):
                raise OpenBDXError("This duck is already connected. Disconnect it before creating another pairing code.")
            name = str(display_name or self._state.get("display_name") or socket.gethostname()).strip()[:120]
        response = self.client.request(
            "POST",
            "/api/device/code",
            json_body={"client_id": "puddleduck", "device_name": name, "scopes": [
                "profile:read", "works:read", "works:publish", "downloads:read",
                "duck:register", "duck:heartbeat", "duck:jobs",
            ]},
        )
        expires_in = int(response.get("expires_in") or 900)
        pending = {
            "device_code": str(response["device_code"]),
            "user_code": str(response["user_code"]),
            "verification_uri": str(response["verification_uri"]),
            "verification_uri_complete": str(response.get("verification_uri_complete") or response["verification_uri"]),
            "interval": max(1, int(response.get("interval") or 5)),
            "expires_at_epoch": time.time() + expires_in,
        }
        with self._lock:
            self._state["display_name"] = name
            self._state["pending"] = pending
            self._state["last_error"] = ""
            self._write_state()
        self._wake.set()
        return self.status()

    def disconnect(self) -> Dict[str, Any]:
        token = ""
        with self._lock:
            token = str(self._state.get("access_token") or "")
        if token:
            try:
                self.client.request("DELETE", "/api/auth/app-token/current", token=token)
            except OpenBDXError:
                pass
        with self._lock:
            keep = {
                "format": CONFIG_FORMAT,
                "origin": self._state["origin"],
                "device_uuid": self._state["device_uuid"],
                "display_name": self._state.get("display_name") or socket.gethostname(),
                "access_token": "",
                "token_expires_at": "",
                "profile": {},
                "duck_id": "",
                "pending": {},
                "installs": {},
                "published": self._state.get("published") or {},
                "last_sync_at": "",
                "last_error": "",
            }
            self._state = keep
            self._write_state()
        self._wake.set()
        return self.status()

    def sync_now(self) -> Dict[str, Any]:
        if not self._state.get("access_token"):
            raise OpenBDXError("Connect this duck to OpenBDX first.")
        self._wake.set()
        return self.status()

    # ------------------------------------------------------------------
    # Robot identity and inventory
    # ------------------------------------------------------------------
    def _release_value(self, keys: Iterable[str]) -> str:
        try:
            text = self._release_path.read_text(encoding="utf-8")
        except OSError:
            return ""
        values: Dict[str, str] = {}
        for line in text.splitlines():
            if "=" not in line:
                continue
            key, value = line.split("=", 1)
            values[key.strip()] = value.strip().strip('"\'')
        for key in keys:
            if values.get(key):
                return values[key]
        return ""

    def _firmware_version(self) -> str:
        return self._release_value(("BDX_VERSION", "VERSION", "IMAGE_VERSION")) or platform.release()

    def _runtime_version(self) -> str:
        try:
            from importlib import metadata
            return metadata.version("puddleduck")
        except Exception:
            return "unknown"

    @staticmethod
    def _canonical_robot_selection(value: Any) -> Optional[str]:
        raw = str(value or "").strip().lower()
        for prefix in ("darkwing4_bdx::", "darkwing4_bdx_"):
            if raw.startswith(prefix):
                raw = raw[len(prefix):]
                break
        return ROBOT_SELECTIONS.get(raw)

    @classmethod
    def _selection_from_options(cls, value: Any) -> Optional[str]:
        """Resolve ``duck=<variant>`` from the runtime options report.

        The viewer's ``auto`` value means follow the mapping in the active
        PuddleDuck configuration.  The body runtime reports that mapping in the
        same ``options`` field displayed by the web UI, for example
        ``robot=darkwing4_bdx options=duck=patch``.
        """
        candidates: List[str] = []
        if isinstance(value, dict):
            for key, enabled in value.items():
                key_text = str(key or "").strip()
                if key_text.lower() == "duck" and isinstance(enabled, str):
                    candidates.append(f"duck={enabled}")
                elif enabled:
                    candidates.append(key_text)
        elif isinstance(value, (list, tuple, set)):
            candidates.extend(str(item or "") for item in value)
        else:
            candidates.append(str(value or ""))

        for candidate in candidates:
            match = ROBOT_OPTION_RE.search(candidate)
            if not match:
                continue
            resolved = cls._canonical_robot_selection(match.group(1))
            if resolved:
                return resolved
        return None

    def _robot_identity(self) -> Dict[str, Any]:
        viewer_selection = "auto"
        if self.duck_selection is not None:
            try:
                viewer_selection = str(self.duck_selection.load() or "auto").strip().lower()
            except Exception:
                viewer_selection = "auto"

        try:
            state = self.state_hub.snapshot()
        except Exception:
            state = {}
        options = state.get("options") if isinstance(state, dict) else None

        if viewer_selection in AUTO_ROBOT_SELECTIONS:
            resolved = self._selection_from_options(options)
            if not resolved:
                raise OpenBDXError(
                    "Waiting for the configured Duck variant from PuddleDuck runtime state "
                    "(expected options=duck=<variant>)."
                )
            mode = "auto"
        else:
            resolved = self._canonical_robot_selection(viewer_selection)
            if not resolved:
                raise OpenBDXError(f"Unknown PuddleDuck viewer Duck selection: {viewer_selection}")
            mode = "explicit"

        return {
            "robot_selection": resolved,
            "robot_selection_mode": mode,
            "robot_options": options,
        }

    def _robot_selection(self) -> str:
        return str(self._robot_identity()["robot_selection"])

    def _capabilities(self) -> Dict[str, Any]:
        return {
            "schema": 1,
            "publishing": ["emote", "policy"],
            "installation": ["emote", "policy"],
            "policy_activation": True,
            "emote_preview": {
                "format": EMOTE_PREVIEW_FORMAT,
                "width": EMOTE_PREVIEW_WIDTH,
                "height": EMOTE_PREVIEW_HEIGHT,
                "fps": EMOTE_PREVIEW_FPS,
                "duration_seconds": EMOTE_PREVIEW_DURATION_SECONDS,
            },
            "runtime": "puddleduck",
            "python": platform.python_version(),
            "platform": platform.platform(),
        }

    def _sha256_path(self, path: Path) -> str:
        stat = path.stat()
        key = (str(path), int(stat.st_mtime_ns), int(stat.st_size))
        cached = self._hash_cache.get(key)
        if cached:
            return cached
        digest = hashlib.sha256()
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(chunk)
        value = digest.hexdigest()
        self._hash_cache = {cache_key: hash_value for cache_key, hash_value in self._hash_cache.items() if cache_key[0] != str(path)}
        self._hash_cache[key] = value
        return value

    @staticmethod
    def _mp4_has_ftyp(path: Path) -> bool:
        try:
            with path.open("rb") as source:
                prefix = source.read(12)
        except OSError:
            return False
        return len(prefix) >= 12 and prefix[4:8] == b"ftyp"

    def _emote_preview(
        self,
        filename: str,
        document: Dict[str, Any],
        upload_filename: str,
    ) -> Tuple[Optional[Dict[str, Any]], Optional[bytes]]:
        """Return a validated on-duck Duckmation preview when one exists."""

        preview_lookup = getattr(self.emote_library, "preview_path", None)
        if not callable(preview_lookup):
            return None, None
        try:
            preview_path = Path(preview_lookup(filename))
        except FileNotFoundError:
            return None, None
        if preview_path.stat().st_size > MAX_PUBLICATION_BYTES:
            raise OpenBDXError(
                "The emote preview is too large for the current OpenBDX publication endpoint."
            )
        if not self._mp4_has_ftyp(preview_path):
            raise OpenBDXError(
                f"The Duckmation preview {preview_path.name} is not a valid MP4 file."
            )

        size = int(preview_path.stat().st_size)
        digest = self._sha256_path(preview_path)
        declared = document.get("openbdx_preview")
        if isinstance(declared, dict):
            checks = {
                "format": EMOTE_PREVIEW_FORMAT,
                "width": EMOTE_PREVIEW_WIDTH,
                "height": EMOTE_PREVIEW_HEIGHT,
                "fps": EMOTE_PREVIEW_FPS,
                "duration_seconds": EMOTE_PREVIEW_DURATION_SECONDS,
                "media_type": "video/mp4",
                "size_bytes": size,
                "sha256": digest,
            }
            for key, expected in checks.items():
                actual = declared.get(key)
                if actual is None:
                    continue
                if key == "duration_seconds":
                    try:
                        matches = abs(float(actual) - float(expected)) <= 1e-6
                    except (TypeError, ValueError):
                        matches = False
                else:
                    matches = actual == expected
                if not matches:
                    raise OpenBDXError(
                        f"The saved Duckmation preview metadata does not match {preview_path.name} ({key}). "
                        "Open the emote in Duckmation and save it again."
                    )

        descriptor = {
            "format": EMOTE_PREVIEW_FORMAT,
            "width": EMOTE_PREVIEW_WIDTH,
            "height": EMOTE_PREVIEW_HEIGHT,
            "fps": EMOTE_PREVIEW_FPS,
            "duration_seconds": EMOTE_PREVIEW_DURATION_SECONDS,
            "codec": "h264",
            "muted": True,
            "filename": upload_filename,
            "media_type": "video/mp4",
            "size_bytes": size,
            "sha256": digest,
        }
        return descriptor, preview_path.read_bytes()

    def _inventory_files(self) -> Dict[str, Any]:
        policies: List[Dict[str, Any]] = []
        active_policy = ""
        try:
            listing = self.policy_store.list()
            active_policy = str(listing.get("active") or "")
            for item in listing.get("policies") or []:
                name = str(item.get("name") or "")
                try:
                    path = self.policy_store.download_path(name)
                    policies.append({
                        "filename": name,
                        "size_bytes": path.stat().st_size,
                        "sha256": self._sha256_path(path),
                        "active": bool(item.get("active")),
                    })
                except Exception:
                    continue
        except Exception:
            policies = []
        emotes: List[Dict[str, Any]] = []
        try:
            snapshot = self.emote_library.snapshot()
            for item in snapshot.get("emotes") or []:
                try:
                    path = self.emote_library.download_path(item.get("source"), item.get("filename"))
                    emotes.append({
                        "filename": str(item.get("filename") or ""),
                        "size_bytes": path.stat().st_size,
                        "sha256": self._sha256_path(path),
                    })
                except Exception:
                    continue
        except Exception:
            emotes = []

        installs: List[Dict[str, Any]] = []
        with self._lock:
            saved = dict(self._state.get("installs") or {})
        changed = False
        for version_id, record in saved.items():
            if not isinstance(record, dict):
                changed = True
                continue
            kind = str(record.get("kind") or "")
            filename = str(record.get("filename") or "")
            expected = str(record.get("sha256") or "")
            try:
                path = self.emote_library.download_path("user", filename) if kind == "emote" else self.policy_store.download_path(filename)
                actual = self._sha256_path(path)
            except Exception:
                changed = True
                continue
            if expected and actual != expected:
                changed = True
                continue
            installs.append({
                "version_id": version_id,
                "kind": kind,
                "filename": filename,
                "sha256": actual,
                "size_bytes": path.stat().st_size,
                "active": kind != "policy" or filename == active_policy,
            })
        if changed:
            with self._lock:
                self._state["installs"] = {item["version_id"]: item for item in installs}
                self._write_state()
        return {"emotes": emotes, "policies": policies, "active_policy": active_policy or None, "installs": installs}

    def _register(self) -> None:
        with self._lock:
            token = str(self._state.get("access_token") or "")
            display_name = str(self._state.get("display_name") or socket.gethostname())
        if not token:
            return
        identity = self._robot_identity()
        response = self.client.request("POST", "/api/duck/register", token=token, json_body={
            "device_uuid": self._state["device_uuid"],
            "display_name": display_name,
            "hostname": socket.gethostname(),
            **identity,
            "firmware_version": self._firmware_version(),
            "runtime_version": self._runtime_version(),
            "capabilities": self._capabilities(),
        })
        duck = response.get("duck") or {}
        with self._lock:
            self._state["duck_id"] = str(duck.get("id") or self._state.get("duck_id") or "")
            self._state["last_error"] = ""
            self._write_state()

    def _heartbeat(self) -> None:
        with self._lock:
            token = str(self._state.get("access_token") or "")
            duck_id = str(self._state.get("duck_id") or "")
        if not token:
            return
        if not duck_id:
            self._register()
            with self._lock:
                duck_id = str(self._state.get("duck_id") or "")
        identity = self._robot_identity()
        response = self.client.request("POST", "/api/duck/heartbeat", token=token, json_body={
            "robot_id": duck_id,
            "firmware_version": self._firmware_version(),
            "runtime_version": self._runtime_version(),
            **identity,
            "inventory": self._inventory_files(),
        })
        del response
        with self._lock:
            self._state["last_sync_at"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
            self._state["last_error"] = ""
            self._write_state()

    # ------------------------------------------------------------------
    # Exact-revision installation
    # ------------------------------------------------------------------
    def _download_job_file(self, job: Dict[str, Any]) -> Tuple[Path, str, int]:
        token = str(self._state.get("access_token") or "")
        claim = str(job.get("claim_token") or "")
        expected_size = int(job.get("expected_size_bytes") or 0)
        expected_hash = str(job.get("expected_sha256") or "").lower()
        if expected_size <= 0 or len(expected_hash) != 64:
            raise OpenBDXError("OpenBDX returned an invalid install descriptor.")
        fd, temp_name = tempfile.mkstemp(prefix=".openbdx-install-", suffix=".part")
        os.close(fd)
        temp = Path(temp_name)
        digest = hashlib.sha256()
        try:
            raw, _headers, _status = self.client.request(
                "GET", str(job.get("download_url") or ""), token=token,
                headers={"X-OpenBDX-Claim-Token": claim}, expect_json=False,
                timeout=max(REQUEST_TIMEOUT_SECONDS, 300.0),
            )
            temp.write_bytes(raw)
            digest.update(raw)
            size = len(raw)
            actual = digest.hexdigest()
            if size != expected_size:
                raise OpenBDXError(f"Downloaded {size} bytes; OpenBDX expected {expected_size}.")
            if actual != expected_hash:
                raise OpenBDXError("Downloaded file SHA-256 does not match the queued OpenBDX revision.")
            return temp, actual, size
        except Exception:
            try:
                temp.unlink()
            except FileNotFoundError:
                pass
            raise

    def _report_job(self, job: Dict[str, Any], state: str, **extra: Any) -> None:
        token = str(self._state.get("access_token") or "")
        payload = {"claim_token": job.get("claim_token"), "state": state}
        payload.update(extra)
        self.client.request("POST", f"/api/duck/jobs/{quote(str(job['id']), safe='')}/status", token=token, json_body=payload)

    def _install_job(self, job: Dict[str, Any]) -> None:
        temp: Optional[Path] = None
        try:
            self._report_job(job, "downloading", progress_bytes=0, message="Downloading exact OpenBDX revision.")
            temp, digest, size = self._download_job_file(job)
            target_name = str(job.get("target_filename") or "")
            kind = str(job.get("artifact_kind") or "")
            with temp.open("rb") as stream:
                if kind == "emote":
                    self.emote_library.upload(target_name, stream, size, overwrite=True)
                elif kind == "policy":
                    self.policy_store.upload(target_name, stream, size)
                    if bool(job.get("activate_after_install")):
                        self.policy_store.set_active(target_name)
                else:
                    raise OpenBDXError(f"Unsupported install kind: {kind}")
            record = {
                "version_id": str(job.get("version_id") or ""),
                "kind": kind,
                "filename": target_name,
                "sha256": digest,
                "size_bytes": size,
                "active": kind != "policy" or self.policy_store.active_name() == target_name,
            }
            with self._lock:
                installs = dict(self._state.get("installs") or {})
                installs[record["version_id"]] = record
                self._state["installs"] = installs
                self._write_state()
            self._report_job(job, "installed", progress_bytes=size, sha256=digest, size_bytes=size, message="Installed on PuddleDuck.")
        except Exception as exc:
            try:
                self._report_job(job, "failed", progress_bytes=0, message=str(exc)[:900])
            except Exception:
                pass
            raise
        finally:
            if temp is not None:
                try:
                    temp.unlink()
                except FileNotFoundError:
                    pass

    def _poll_job(self) -> None:
        if bool(self.state_hub.policy_active()):
            return
        token = str(self._state.get("access_token") or "")
        if not token or not self._state.get("duck_id"):
            return
        response = self.client.request("GET", "/api/duck/jobs/next", token=token)
        job = response.get("job") if isinstance(response, dict) else None
        if isinstance(job, dict):
            self._set_busy(f"Installing {job.get('artifact_title') or job.get('target_filename')}")
            try:
                self._install_job(job)
            finally:
                self._set_busy("")

    # ------------------------------------------------------------------
    # Publication from local Duckmation / policy store
    # ------------------------------------------------------------------
    @staticmethod
    def _slug(value: str) -> str:
        text = "".join(character.lower() if character.isalnum() else "-" for character in str(value or "").strip())
        while "--" in text:
            text = text.replace("--", "-")
        text = text.strip("-")[:100]
        if len(text) < 3:
            raise OpenBDXError("A publication slug must contain at least three letters or numbers.")
        return text

    @staticmethod
    def _tags(value: Any) -> List[str]:
        if isinstance(value, list):
            values = value
        else:
            values = str(value or "").split(",")
        result: List[str] = []
        for item in values:
            tag = str(item).strip().lower().replace(" ", "-")[:40]
            if tag and tag not in result:
                result.append(tag)
        return result[:16]

    def _publication_fields(self, metadata: Dict[str, Any], default_title: str) -> Dict[str, Any]:
        title = str(metadata.get("title") or default_title).strip()[:120]
        if not title:
            raise OpenBDXError("Publication title is required.")
        summary = str(metadata.get("summary") or f"Published from {self._state.get('display_name') or 'PuddleDuck'}.").strip()[:280]
        if not summary:
            raise OpenBDXError("Publication summary is required.")
        visibility = str(metadata.get("visibility") or "public").lower()
        if visibility not in {"private", "unlisted", "public"}:
            raise OpenBDXError("Visibility must be private, unlisted, or public.")
        return {
            "title": title,
            "slug": self._slug(str(metadata.get("slug") or title)),
            "summary": summary,
            "description": str(metadata.get("description") or "").strip()[:20000],
            "license_spdx": str(metadata.get("license_spdx") or "CC-BY-4.0").strip()[:80],
            "allow_remixes": bool(metadata.get("allow_remixes", True)),
            "visibility": visibility,
            "tags": self._tags(metadata.get("tags")),
            "version_label": str(metadata.get("version_label") or "1.0.0").strip()[:80],
            "changelog": str(metadata.get("changelog") or "Published from PuddleDuck.").strip()[:10000],
        }

    def _server_config(self) -> Dict[str, Any]:
        return self.client.request("GET", "/api/config", token=str(self._state.get("access_token") or ""))

    def _publish_bytes(self, publication: Dict[str, Any], files: Dict[str, bytes]) -> Dict[str, Any]:
        token = str(self._state.get("access_token") or "")
        if not token:
            raise OpenBDXError("Connect this duck to OpenBDX before publishing.")
        response = self.client.request("POST", "/api/publishing/drafts", token=token, json_body=publication)
        draft = response.get("draft") or {}
        try:
            for upload in response.get("uploads") or []:
                filename = str(upload.get("filename") or "")
                payload = files.get(filename)
                if payload is None:
                    raise OpenBDXError(f"OpenBDX requested an unexpected file: {filename}")
                self.client.request(
                    "PUT", str(upload.get("upload_url") or ""), token=token, data=payload,
                    headers={"Content-Type": str(upload.get("media_type") or "application/octet-stream")},
                )
            result = self.client.request("POST", f"/api/publishing/versions/{quote(str(draft['version_id']), safe='')}/finalize", token=token, json_body={})
            return result
        except Exception:
            try:
                self.client.request("DELETE", f"/api/publishing/versions/{quote(str(draft.get('version_id') or ''), safe='')}", token=token)
            except Exception:
                pass
            raise

    def publish_emote(self, filename: str, metadata: Dict[str, Any]) -> Dict[str, Any]:
        path = self.emote_library.download_path("user", filename)
        if path.stat().st_size > MAX_PUBLICATION_BYTES:
            raise OpenBDXError("The emote is too large for the current OpenBDX publication endpoint.")
        try:
            document = json.loads(path.read_text(encoding="utf-8"))
        except Exception as exc:
            raise OpenBDXError(f"Unable to read emote JSON: {exc}") from exc
        if not isinstance(document, dict) or document.get("format") != "darkwing_emote_control_v1":
            raise OpenBDXError("Only darkwing_emote_control_v1 emotes can be published.")
        project = document.get("duckmation_project")
        if not isinstance(project, dict) or project.get("format") != "duckmation_emote_keyframes_v1":
            raise OpenBDXError("This emote does not contain editable Duckmation keyframes.")
        fields = self._publication_fields(metadata, str(document.get("name") or path.stem))
        preview_filename = f"{fields['slug']}.preview.mp4"
        preview, preview_bytes = self._emote_preview(
            filename, document, preview_filename
        )
        config = self._server_config()
        robot_pack = str((config.get("robot_pack") or {}).get("sha256") or config.get("model_archive_sha256") or "").lower()
        if len(robot_pack) != 64:
            raise OpenBDXError("OpenBDX did not advertise the active Darkwing robot-pack identity.")
        profile = dict(self._state.get("profile") or {})
        author = str(profile.get("display_name") or "").strip()
        handle = str(profile.get("handle") or "").strip()
        if not author or not handle:
            raise OpenBDXError("The connected OpenBDX account profile is incomplete.")
        channels = [str(item) for item in document.get("channels") or []]
        frames = document.get("frames") or []
        if not channels or not isinstance(frames, list) or not frames:
            raise OpenBDXError("The emote runtime has no channels or frames.")
        rate = int(document.get("rate_hz") or 50)
        duration = float(document.get("duration_s") or (len(frames) / float(rate)))
        solver_version = str((document.get("openbdx_manifest") or {}).get("solver", {}).get("version") or metadata.get("placo_version") or "0.9.23-0")
        artifact_id = str((document.get("openbdx_manifest") or {}).get("artifact_id") or "")
        robot_selection = self._robot_selection()
        document["author"] = author
        document["author_handle"] = handle
        project["author"] = author
        project["author_handle"] = handle
        manifest = {
            "format": "openbdx_emote_manifest_v1",
            "artifact_kind": "emote",
            "origin": str(self._state["origin"]),
            **({"artifact_id": artifact_id} if artifact_id else {}),
            "work": {
                "slug": fields["slug"], "title": fields["title"], "summary": fields["summary"],
                "description": fields["description"], "license_spdx": fields["license_spdx"],
                "allow_remixes": fields["allow_remixes"], "visibility": fields["visibility"], "tags": fields["tags"],
            },
            "version": {
                "label": fields["version_label"], "changelog": fields["changelog"],
                "bundle_format": "openbdx_emote_bundle_v1", "source_format": "duckmation_emote_keyframes_v1",
                "runtime_format": "darkwing_emote_control_v1", "rate_hz": rate,
                "duration_seconds": duration, "frame_count": len(frames), "channels": channels, "preview": preview,
            },
            "creator": {"display_name": author, "handle": handle},
            "robot": {"model": ROBOT_MODEL, "selection": robot_selection, "robot_pack_sha256": robot_pack},
            "solver": {"name": "placo", "version": solver_version, "compile_mode": "local_duckmation"},
            "lineage": None,
        }
        document["openbdx_manifest"] = manifest
        encoded = (json.dumps(document, indent=2, ensure_ascii=False) + "\n").encode("utf-8")
        digest = hashlib.sha256(encoded).hexdigest()
        publication: Dict[str, Any] = {
            **({"artifact_id": artifact_id} if artifact_id else {}),
            "work": {
                "kind": "emote", "slug": fields["slug"], "title": fields["title"], "summary": fields["summary"],
                "description": fields["description"], "license_spdx": fields["license_spdx"],
                "allow_remixes": fields["allow_remixes"], "visibility": fields["visibility"], "tags": fields["tags"],
            },
            "version": {
                "label": fields["version_label"], "changelog": fields["changelog"], "format_name": "openbdx_emote_bundle_v1",
                "format_version": "1", "robot_model": ROBOT_MODEL, "robot_selection": robot_selection,
                "robot_pack_sha256": robot_pack, "runtime_contract_version": "darkwing_emote_control_v1",
                "compatibility": {ROBOT_MODEL: True},
                "payload": {
                    "bundle_format": "openbdx_emote_bundle_v1", "source_embedded": True,
                    "source_format": "duckmation_emote_keyframes_v1", "runtime_format": "darkwing_emote_control_v1",
                    "rate_hz": rate, "duration_seconds": duration, "frame_count": len(frames), "channels": channels,
                    "preview": preview,
                    "solver": {"name": "placo", "version": solver_version, "compile_mode": "local_duckmation", "diagnostics": {}},
                },
            },
            "files": [{
                "role": "runtime", "filename": f"{fields['slug']}.json", "media_type": "application/json",
                "size_bytes": len(encoded), "sha256": digest, "is_public_preview": True,
            }],
        }
        publication_files = {f"{fields['slug']}.json": encoded}
        if preview is not None and preview_bytes is not None:
            publication["files"].append({
                "role": "preview",
                "filename": preview_filename,
                "media_type": "video/mp4",
                "size_bytes": len(preview_bytes),
                "sha256": preview["sha256"],
                "is_public_preview": True,
            })
            publication_files[preview_filename] = preview_bytes
        result = self._publish_bytes(publication, publication_files)
        version = result.get("version") or {}
        descriptor = version.get("version") if isinstance(version, dict) else {}
        returned_artifact = str((version.get("work") or {}).get("id") or publication.get("artifact_id") or "") if isinstance(version, dict) else ""
        returned_version = str((descriptor or {}).get("id") or "") if isinstance(descriptor, dict) else ""
        if returned_artifact:
            document["openbdx_manifest"]["artifact_id"] = returned_artifact
        if returned_version:
            document["openbdx_manifest"]["version_id"] = returned_version
        try:
            path.write_text(json.dumps(document, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
            os.chmod(str(path), 0o600)
        except OSError:
            pass
        with self._lock:
            published = dict(self._state.get("published") or {})
            published[f"emote:{filename}"] = {"artifact_id": returned_artifact, "version_id": returned_version, "slug": fields["slug"]}
            self._state["published"] = published
            self._write_state()
        return result

    def publish_policy(self, filename: str, metadata: Dict[str, Any]) -> Dict[str, Any]:
        path = self.policy_store.download_path(filename)
        if path.suffix.lower() != ".onnx":
            raise OpenBDXError("Only ONNX policy files can be published.")
        if path.stat().st_size > MAX_PUBLICATION_BYTES:
            raise OpenBDXError("The policy is too large for the current OpenBDX publication endpoint.")
        fields = self._publication_fields(metadata, path.stem.replace("_", " ").title())
        config = self._server_config()
        robot_pack = str((config.get("robot_pack") or {}).get("sha256") or config.get("model_archive_sha256") or "").lower()
        if len(robot_pack) != 64:
            raise OpenBDXError("OpenBDX did not advertise the active Darkwing robot-pack identity.")
        data = path.read_bytes()
        digest = hashlib.sha256(data).hexdigest()
        published_record = dict(self._state.get("published") or {}).get(f"policy:{filename}") or {}
        artifact_id = str(published_record.get("artifact_id") or "")
        robot_selection = self._robot_selection()
        publication: Dict[str, Any] = {
            **({"artifact_id": artifact_id} if artifact_id else {}),
            "work": {
                "kind": "policy", "slug": fields["slug"], "title": fields["title"], "summary": fields["summary"],
                "description": fields["description"], "license_spdx": fields["license_spdx"],
                "allow_remixes": fields["allow_remixes"], "visibility": fields["visibility"], "tags": fields["tags"],
            },
            "version": {
                "label": fields["version_label"], "changelog": fields["changelog"], "format_name": "onnx", "format_version": "1",
                "robot_model": ROBOT_MODEL, "robot_selection": robot_selection, "robot_pack_sha256": robot_pack,
                "runtime_contract_version": "puddleduck_policy_runtime_v1", "compatibility": {ROBOT_MODEL: True},
                "payload": {"format": "onnx", "metadata_mode": "model", "runtime_contract": "puddleduck_policy_runtime_v1"},
            },
            "files": [{
                "role": "runtime", "filename": f"{fields['slug']}.onnx", "media_type": "application/octet-stream",
                "size_bytes": len(data), "sha256": digest, "is_public_preview": True,
            }],
        }
        result = self._publish_bytes(publication, {f"{fields['slug']}.onnx": data})
        version = result.get("version") or {}
        descriptor = version.get("version") if isinstance(version, dict) else {}
        returned_artifact = str((version.get("work") or {}).get("id") or artifact_id) if isinstance(version, dict) else artifact_id
        returned_version = str((descriptor or {}).get("id") or "") if isinstance(descriptor, dict) else ""
        with self._lock:
            published = dict(self._state.get("published") or {})
            published[f"policy:{filename}"] = {"artifact_id": returned_artifact, "version_id": returned_version, "slug": fields["slug"]}
            self._state["published"] = published
            self._write_state()
        return result

    # ------------------------------------------------------------------
    # Background loop
    # ------------------------------------------------------------------
    def _set_busy(self, value: str) -> None:
        with self._lock:
            self._busy = str(value or "")

    def _record_error(self, error: Exception) -> None:
        with self._lock:
            self._state["last_error"] = str(error)[:1000]
            self._write_state()

    @staticmethod
    def _retry_delay_seconds(error: OpenBDXError) -> float:
        """Return a bounded delay for a failed background request.

        OpenBDX rate-limit details are nested under ``detail``.  Respect the
        advertised window so a failed registration cannot retry every second
        and keep the account rate-limited indefinitely.
        """
        detail = error.payload.get("detail") if isinstance(error.payload, dict) else None
        retry_value = None
        if isinstance(detail, dict):
            retry_value = detail.get("retry_after_seconds")
        if retry_value is None and isinstance(error.payload, dict):
            retry_value = error.payload.get("retry_after_seconds")
        try:
            retry_after = float(retry_value)
        except (TypeError, ValueError):
            retry_after = 0.0
        if error.status == 429:
            return min(900.0, max(5.0, retry_after or 60.0))
        if error.status == 0 or error.status >= 500:
            return 30.0
        return 15.0

    def _poll_pairing(self) -> bool:
        with self._lock:
            pending = dict(self._state.get("pending") or {})
        if not pending:
            return False
        if float(pending.get("expires_at_epoch") or 0) <= time.time():
            with self._lock:
                self._state["pending"] = {}
                self._state["last_error"] = "OpenBDX connection code expired."
                self._write_state()
            return False
        try:
            response = self.client.request("POST", "/api/device/token", json_body={"device_code": pending.get("device_code")})
        except OpenBDXError as exc:
            if exc.code == "authorization_pending" or exc.status == 428:
                return True
            if exc.code in {"access_denied", "expired_token", "device_code_consumed"}:
                with self._lock:
                    self._state["pending"] = {}
                    self._state["last_error"] = str(exc)
                    self._write_state()
                return False
            raise
        with self._lock:
            self._state["access_token"] = str(response.get("access_token") or "")
            self._state["token_expires_at"] = str(response.get("expires_at") or "")
            self._state["profile"] = response.get("profile") if isinstance(response.get("profile"), dict) else {}
            self._state["pending"] = {}
            self._state["last_error"] = ""
            self._write_state()
        self._register()
        self._heartbeat()
        return False

    def _run(self) -> None:
        next_pair = next_heartbeat = next_job = 0.0
        while not self._stop.is_set():
            now = time.monotonic()
            try:
                with self._lock:
                    pending = bool(self._state.get("pending"))
                    connected = bool(self._state.get("access_token"))
                if pending and now >= next_pair:
                    self._set_busy("Waiting for OpenBDX approval")
                    self._poll_pairing()
                    next_pair = now + PAIR_POLL_SECONDS
                    self._set_busy("")
                elif connected:
                    if now >= next_heartbeat:
                        self._set_busy("Synchronizing with OpenBDX")
                        self._heartbeat()
                        next_heartbeat = now + HEARTBEAT_SECONDS
                        self._set_busy("")
                    if now >= next_job:
                        self._poll_job()
                        next_job = now + JOB_POLL_SECONDS
            except OpenBDXError as exc:
                self._record_error(exc)
                retry_at = now + self._retry_delay_seconds(exc)
                next_pair = max(next_pair, retry_at)
                next_heartbeat = max(next_heartbeat, retry_at)
                next_job = max(next_job, retry_at)
                if exc.status in (401, 403) and exc.code in {"invalid_app_token", "app_token_expired", "app_token_revoked", "duck_revoked"}:
                    with self._lock:
                        self._state["access_token"] = ""
                        self._state["duck_id"] = ""
                        self._state["profile"] = {}
                        self._write_state()
            except Exception as exc:
                self._record_error(exc)
                retry_at = now + 15.0
                next_pair = max(next_pair, retry_at)
                next_heartbeat = max(next_heartbeat, retry_at)
                next_job = max(next_job, retry_at)
            self._set_busy("")
            self._wake.wait(timeout=1.0)
            self._wake.clear()
